var UsuarioControlComponent = class {
  constructor(http, snackBar) {
    this.http = http;
    this.snackBar = snackBar;
  }
  nuevoUsuario = {
    dni: "",
    nombre: "",
    direccion: "",
    email: "",
    clave: "",
    password: ""
  };
  fotoSeleccionada = null;
  archivoSeleccionado = null;
  datosActualizadosOferta;
  miFormulario;
  seleccionarArchivo(event, tipo) {
    const archivo = event.target.files[0];
    if (tipo === "foto") {
      this.fotoSeleccionada = archivo;
    } else if (tipo === "cv") {
      this.archivoSeleccionado = archivo;
    }
  }
  crearUsuario(event) {
    event.preventDefault();
    if (!this.nuevoUsuario.dni || !this.nuevoUsuario.nombre || !this.nuevoUsuario.direccion || !this.nuevoUsuario.email || !this.nuevoUsuario.clave || !this.nuevoUsuario.password || !this.fotoSeleccionada || !this.archivoSeleccionado) {
      alert("Por favor, completa todos los campos.");
      return;
    }
    if (this.fotoSeleccionada.size > 5 * 1024 * 1024) {
      alert(
        "El archivo de la foto es demasiado grande. M\xE1ximo permitido: 5 MB"
      );
      return;
    }
    if (this.archivoSeleccionado.size > 5 * 1024 * 1024) {
      alert("El archivo del CV es demasiado grande. M\xE1ximo permitido: 5 MB");
      return;
    }
    const formData = new FormData();
    formData.append("dni", this.nuevoUsuario.dni);
    formData.append("nombre", this.nuevoUsuario.nombre);
    formData.append("direccion", this.nuevoUsuario.direccion);
    formData.append("email", this.nuevoUsuario.email);
    formData.append("clave", this.nuevoUsuario.clave);
    formData.append("password", this.nuevoUsuario.password);
    formData.append("foto", this.fotoSeleccionada);
    formData.append("uploadcv", this.archivoSeleccionado);
    formData.forEach((value, key) => {
      if (!value) {
        console.error(`El valor del campo ${key} es inv\xE1lido.`);
      }
    });
    this.http.post("http://localhost:8080/perfiles", formData, {
      observe: "response"
      // Observa toda la respuesta HTTP
    }).subscribe({
      next: (response2) => {
        if (response2.status === 201 || response2.status === 200) {
          this.snackBar.open("Usuario creado satisfactoriamente", "Cerrar", {
            duration: 3e3
          });
        }
      },
      error: (response2) => {
        console.error("Error al crear el Usuario", response2);
        this.snackBar.open("Error al crear el Usuario", "Cerrar", {
          duration: 3e3
        });
      }
    });
  }
};
